/**
 * Respuesta de `/v1/sync/verificar-claves`.
 */
export type VerificacionClaves = { tablas: Array<ClavesTabla>, };

/**
 * Respuesta de `/v1/sync/verificar`: la foto con la que se contrasta.
 *
 * `ventana` reusa `BootstrapTabla` porque es exactamente la misma forma y la construye la misma
 * sentencia del worker: tener dos formas para el mismo volcado sería tener dos que pueden divergir.
 */
export type VerificacionNube = { conteos: Array<ConteoTabla>, ventana: Array<BootstrapTabla>, 
/**
 * La ventana no cabía y sólo vienen los conteos. Media comprobación es mejor que ninguna.
 */
ventana_omitida: boolean, 
/**
 * Límite inferior de la ventana que usó el worker (informativo).
 */
desde: string, 
/**
 * SYNC-25: hasta qué `Seq` del log de la nube llega esta foto, **leído después de las filas**.
 *
 * Es lo que permite borrar arriba sin peligro. Si el checkpoint local llega hasta aquí, esta
 * Main ya ha visto todo lo que viaja en la foto, así que una fila que le falte no puede ser
 * «algo que acaba de escribir la Handy y todavía no me ha llegado»: es un borrado suyo que no
 * llegó a subir. Si no llega, no se borra nada y se espera al ciclo siguiente.
 *
 * `#[serde(default)]` = 0 con un worker anterior, y 0 nunca alcanza al checkpoint local salvo
 * en una base recién estrenada (donde tampoco hay nada que borrar). Falla cerrado.
 */
hasta_seq: number, };

/**
 * RI-27: sin precio. El de la línea lo pone el catálogo, no la pantalla.
 */
export type VrAddLineaComandaInput = { id_comanda: string, id_producto: string, cantidad: number, };

/**
 * REV-17: quién cobra sale de la **sesión**, nunca de la entrada (SEC-01).
 *
 * Es la misma regla que ya aplican anular un cobro, cerrar la caja y abrir el cajón, y faltaba
 * justo donde más duele: el cobrador que se guarda con el pago es el rastro con el que se
 * investiga un descuadre del cajón. Firmándolo con lo que le pase la pantalla, quien alcance el
 * IPC puede cobrar en efectivo a nombre de otro — o sea, la sisa que ese rastro existe para poder
 * ver. Y no hay sitio donde se cobre sin sesión: a las dos pantallas de venta sólo se llega
 * pasando el login.
 */
export type VrCobrarFraccionadoInput = { 
/**
 * El id del cobro (`Pagos.ID_Pago`), un UUID que genera la pantalla al encolarlo.
 *
 * Es lo que hace idempotente el cobro: si la aplicación se cae después de guardarlo y antes de
 * quitarlo de la cola, al volver se reintenta con el mismo id y se devuelve el número del cobro
 * que ya existe, en vez de rechazarlo por no quedar líneas pendientes.
 */
id_pago: string, id_comanda: string, metodo: string, importe_total: Dinero, detalles: Array<string>, 
/**
 * FISCAL-02: si viene, se emite **factura completa** (`F1`) en vez de un ticket.
 *
 * Se llega aquí por dos caminos: el cliente lo pide («Factura con NIF») o el importe pasa del
 * límite de la simplificada y entonces no hay alternativa. Si pasa del límite y esto va vacío,
 * el cobro se rechaza con `factura_completa_requerida` y la pantalla pide los datos.
 */
destinatario?: DestinatarioInput, };

